TOOL_RESULT read_family:
{"id": "FAM:SF-APPS-088", "document": "# FAM:SF-APPS-088 | Study family SF-APPS-088: Offensive-identity resilience: connector absence vs usage-matched others
- observed_research_question: Offensive-identity resilience: connector absence vs usage-matched others
- auto_outcome_status: supported
- observed_hypothesis: Connector absence displaces team offensive identity (D_A) more than usage-matched non-organizer absence.
- observed_result: Unmatched conn vs role D_A 0.2020 vs 0.1021, t=5.97 p=2.87e-08. Usage-matched vs role: paired dD_A +0.1151, P(conn>ctrl)=81.2%, t=6.35 p=7.35e-09 n=96. Vs terminal: +0.0777 t=2.37 p=0.0261 n=25.
- auto_failure_mechanism: D_positive (no failure: positive result)
- observed_failure_evidence: Usage-matched connector vs role occupant identity break is large and significant (n=96). Licensed comparison excludes organizers.
- observed_sample_and_power: n=96 matched pairs vs role; n=25 vs terminal; 908 player-seasons
- observed_method: Player-seasons >=400 poss on and off, N=908. Primary: usage-matched pairs connector vs role occupant / vs terminal.
- observed_verdict: supported
- observed_failure_type: D_positive
- auto_validation_status: no_validation_recorded; evidence: NOT_RECORDED
- observed_notes: Does not claim PPP value. PRIMARY ORGANIZER is a positive-control reference (mean D_A 0.2141).
- auto_confidence: high (0.95)
- auto_members_disagree: no
- auto_knowable_before_outcome: not_applicable
- observed_project: When a Hub Sits (Paper 2)
- observed_dates: APPS-088: 2026-07-26 (mtime)
- observed_member_records: APPS-088
- observed_sources: APPS-088: C:\Users\lisas\OneDrive\Documents\Basketball\App\Strategy\paper2_output\identity_resilience_report.md
- auto_adjudication_basis: R0 single record; automated rule-based adjudication, not human adjudication
- auto_limited_by: LIM:small_sample {basis=LIMIT_RULES on recorded power, failure evidence and notes; level=unclear}
- auto_has_risk: RISK:MECHANICAL_FLOOR {basis=risk taxonomy rules}
- auto_has_risk: RISK:SAMPLE_SIZE_POWER {basis=risk taxonomy rules}
- auto_related_family: FAM:SF-PAP-014 {basis=family structure, similarity or record links; relation=repeated_by_later_family}
- auto_related_family: FAM:SF17 {basis=family structure, similarity or record links; relation=record_link_related_to}
- auto_related_family: FAM:SF18 {basis=family structure, similarity or record links; relation=record_link_related_to}
- auto_addresses_question: RQC:RQC-013 {basis=TF-IDF question clustering}
- auto_uses_method: METH:matched_control {basis=keyword rules on member records}
- auto_uses_dataset: DS:Box_score_and_traditional_stats {basis=keyword rules on member records}
- auto_uses_dataset: DS:Player_absence_spells {basis=keyword rules on member records}
"}

{
  "action": "final",
  "output": {
    "research_concepts": [
      "player absence",
      "offensive reorganization",
      "points per possession",
      "league-relative baseline",
      "team offensive efficiency change"
    ],
    "methodological_questions": [
      "How to quantify offensive reorganization relative to league norms?",
      "What sample of absence spells provides sufficient power to detect predictive effects?",
      "How to avoid regression-to-the-mean when measuring pre/post PPP change?",
      "Which confounding factors (opponent quality, schedule, concurrent absences) must be controlled?",
      "How to validate the reorganization metric against out-of-sample outcomes?"
    ],
    "historical_evidence": [
      {
        "id": "FAM:SF-APPS-088",
        "status_as_recorded": "supported",
        "finding": "Connector absence displaces team offensive identity (D_A) more than usage-matched non-organizer absence. Unmatched conn vs role D_A 0.2020 vs 0.1021, t=5.97 p=2.87e-08; usage-matched paired dD_A +0.1151, P(conn>ctrl)=81.2%, t=6.35 p=7.35e-09 n=96."
      },
      {
        "id": "FAM:SF20",
        "status_as_recorded": "untestable",
        "finding": "Real player absences move the association structure (V1 confirmed: mean(D_real - median_null)=+0.142, CI[+0.103,+0.187]). However, the LOO simulation failed to predict the magnitude (V2a rho=+0.288 p=0.077 CI[-0.244,+0.667]; V2b rho=+0.253 p=0.115)."
      },
      {
        "id": "FAM:SF-CHT-052",
        "status_as_recorded": "inconclusive",
        "finding": "Play-type replacement similarity does not separate absorption from cascade when a player sits. Mean sim ABSORBED +0.863 vs CASCADE +0.848; Spearman(sim, -gap)=-0.19 (wrong-signed)."
      }
    ],
    "failed_approaches": [
      {
        "id": "FAM:SF20",
        "what_failed": "Predicting the magnitude of structural change under real absence via simulation",
        "why": "V2a and V2b correlations failed to reach significance; LIM:small_sample"
      },
      {
        "id": "FAM:SF-CHT-052",
        "what_failed": "Using play-type similarity of replacement to separate absorption from cascade",
        "why": "Similarity does not discriminate; wrong-signed Spearman correlation; B_powered_null; RISK:LABEL_ERROR"
      },
      {
        "id": "FAM:SF29",
        "what_failed": "Using lineup coverage of core roles to predict points per possession",
        "why": "Covered lineup coefficient +0.42 pts/100, t=0.53, p=0.595; rejected; LIM:low_power_large_MDE; B_powered_null"
      }
    ],
    "evidence_establishes": [
      "Offensive structural change (identity displacement) is measurable and occurs in player absences.",
      "The amount of displacement varies by the organizational role of the absent player (connector > non-organizer).",
      "Real absences move the association structure beyond null expectation (V1 confirmed)."
    ],
    "evidence_does_not_establish": [
      "Whether the magnitude of reorganization relative to league norms predicts the change in points per possession.",
      "Any causal link between reorganization magnitude and team offensive efficiency.",
      "An optimal metric for reorganization, or how to aggregate across play types.",
      "The predictive power of reorganization after controlling for confounders."
    ],
    "own_inferences": [
      "The independent variable 'reorganizes relative to L' requires operationalization; candidate metrics include Jensen-Shannon divergence of play-type distributions, change in role composition, or D_A from SF-APPS-088, all normalized by league-typical shift for similar usage changes.",
      "Regression to the mean threatens pre-post PPP comparisons if extreme pre-absence performance is associated with large reorganization.",
      "Using in-sample PPP changes for both predictor and outcome can induce spurious correlation; outcome should be measured in a holdout period or cross-validated.",
      "148 spells may be underpowered for small effects unless the reorganization metric and PPP change have a strong signal-to-noise ratio."
    ],
    "uncertainties": [
      "The exact definition of 'L' (league) in the question: could be league-average offensive composition shift for similar usage changes, or simply league-average PPP.",
      "Whether the 148 spells are all usable after applying minimum-game filters (pre and post).",
      "The reliability of derived play-type labels and their stability across different lineups and opponents.",
      "How much of the reorganization variance is driven by opponent defensive adjustments vs. genuine offensive change."
    ],
    "historical_effect": {
      "changed_decision": "no",
      "explanation": "Historical evidence confirms that reorganization is measurable and varies by player type, which supports the feasibility of constructing a predictor. However, it also shows that attempts to predict magnitude of change or link structural shifts to efficiency outcomes have been unsuccessful. This does not change the decision to proceed, but reinforces the need for a careful design to avoid previous pitfalls (e.g., small samples, label error, prediction of magnitude)."
    },
    "testability": {
      "p_testable": 0.3,
      "blocking_constraints": [
        {
          "code": "SAMPLE_SIZE_POWER",
          "text": "Only ~148 spells may limit power to detect small-to-moderate correlations; the minimum detectable effect size may be larger than a realistic reorganization signal."
        },
        {
          "code": "RTM_SELECTION",
          "text": "Selecting spells with large reorganization risk pre-period PPP being unusual, inducing regression to the mean in post-period change."
        },
        {
          "code": "CONFOUNDING",
          "text": "Opponent quality, schedule, and concurrent injuries could drive both reorganization and PPP change."
        }
      ]
    },
    "prior_work": {
      "already_answered": "partly",
      "cited": [
        "FAM:SF-APPS-088",
        "FAM:SF20",
        "FAM:SF-CHT-052"
      ],
      "summary": "Previous studies have established that offensive identity (play-type/role structure) changes during player absences and that this change is larger for connectors than for role players. They have not tested whether the degree of reorganization predicts the resulting change in points per possession."
    },
    "risks": [
      {
        "code": "SAMPLE_SIZE_POWER",
        "text": "With 148 spells, power to detect small correlations (rho < 0.2) is low; effect sizes of practical interest may be undetectable."
      },
      {
        "code": "RTM_SELECTION",
        "text": "If spells are selected based on large reorganization, the pre-absence PPP may be extreme, setting up negative PPP change from regression to the mean rather than reorganization."
      },
      {
        "code": "MEASURE_RELIABILITY",
        "text": "The reorganization metric depends on play-type classifications and role labels that contain noise, reducing signal-to-noise ratio."
      },
      {
        "code": "CONFOUNDING",
        "text": "Opponent defensive strength, schedule density, and other injuries simultaneously influence how much a team reorganizes and its PPP change."
      },
      {
        "code": "LEAKAGE_LOOKAHEAD",
        "text": "If reorganization is measured over the same games as the PPP change outcome, the direction of causality is ambiguous; predictive design must separate the two periods."
      },
      {
        "code": "MULTIPLE_TESTING",
        "text": "Multiple candidate reorganization metrics (play-type shift, role change, lineup volatility) could inflate false positive risk if not pre-registered or corrected."
      },
      {
        "code": "MECHANICAL_FLOOR",
        "text": "Reorganization metrics are bounded (e.g., distribution divergences), potentially suppressing variance when the baseline is already extreme."
      }
    ],
    "predicted_outcome": {
      "supported": 0.1,
      "rejected": 0.3,
      "untestable": 0.2,
      "artifact": 0.2,
      "uncertain": 0.2
    },
    "decision": "proceed_with_changes",
    "design": {
      "estimand": "The linear slope of post-absence team points per possession (adjusted for opponent and schedule) on a measure of offensive reorganization (play-type distribution shift relative to league-wide shift for same usage change), among player absence spells.",
      "unit": "One player absence spell: a continuous stretch of missed games by a single player that satisfies minimum filters (>=5 games missed, >=10 games played both before and after, and the player had >=400 on-court and off-court possessions in the same season prior to absence).",
      "sample": "All such spells from NBA 2022-23 through 2025-26 regular seasons and playoffs, with valid play-type data in the derived possession graph database. Expected n ~ 100–148 spells after filters.",
      "power": "With n=100–148, 80% power to detect rho >= 0.25 (two-sided alpha=0.05); a pre-registered minimal effect of interest can be set at rho=0.20 (underpowered if true effect is smaller). Companion equivalence test can be defined for practical null.",
      "controls": "Opponent defensive rating averaged over post-absence games; home/away game proportion; average days of rest between games; indicator for playoff vs regular season; number of additional rotation players missing simultaneously; pre-absence team PPP (to mitigate RTM); calendar-year fixed effects.",
      "falsification": "1) Stratify by absent player role: if the predictive relationship only holds for connector/organizer absences (expected) but not for role players, it supports a specific mechanism. 2) Pseudo-absence: random selection of games for each team (no actual injury) should yield reorganization close to league average and no predictive relationship. 3) Temporal split: train on seasons through 2024-25, test out-of-sample on 2025-26 spells.",
      "multiplicity": "Single pre-registered reorganization metric: Jensen-Shannon divergence between play-type frequency distributions (pre-absence vs post-absence), subtracted by the league-average divergence for that player's usage-level change. Secondary metrics (role composition shift, D_A) reported as robustness checks with Bonferroni-Holm correction.",
      "decision_rule": "One-sided test (expect more reorganization -> larger PPP drop, or vice versa, depending on theory). Reject null if coefficient p < 0.05 (adjusted for controls) after confirming residuals are approximately normal and homoscedastic. If pre-registered out-of-sample test fails to replicate, finding downgraded to suggestive.",
      "data_version": "Data freeze as of 2026-11-01: NBA play-by-play, substitution rotations, starters, defensive matchups, and derived play-type possession records (graph database). Per-game box-score summary for opponent and schedule variables."
    }
  }
}

